def f(n):
    if n == 0:
        return 0
    m = 0
    temp_n = n
    while temp_n % 2 == 0:
        m += 1
        temp_n //= 2
    return temp_n

def check(v, u):
    for i in range(v):
        if (f(u + v + i) - f(u + i)) % 4 != 0:
            return False
    return True

def solve_for_v(v, limit=10000):
    for u in range(1, limit):
        if check(v, u):
            return u
    return None

results = []
for v in range(1, 15):
    res = solve_for_v(v)
    results.append((v, res))

print(results)

